import{_ as a,o,c as s,a3 as r}from"./chunks/framework.Cj_fzHAr.js";const n="/manual/img/tenants/mi-empresa.png",t="/manual/img/tenants/roles.png",q=JSON.parse('{"title":"Mi Empresa","description":"","frontmatter":{},"headers":[],"relativePath":"modulos/tenants.md","filePath":"modulos/tenants.md"}'),l={name:"modulos/tenants.md"};function i(d,e,u,p,c,g){return o(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="mi-empresa" tabindex="-1">Mi Empresa <a class="header-anchor" href="#mi-empresa" aria-label="Permalink to &quot;Mi Empresa&quot;">​</a></h1><p>La sección <strong>Mi Empresa</strong> es donde configuras los datos y la apariencia de tu empresa dentro de la plataforma, además de los <strong>roles</strong> y <strong>cargos</strong> que usarás para tu equipo. Es una pantalla de administración: normalmente la usa el <strong>Administrador</strong>.</p><p>Cada empresa funciona de forma <strong>independiente y aislada</strong>: tus obras, personas y documentos solo los ve tu empresa. Aquí defines cómo se ve y cómo se organiza ese espacio.</p><h2 id="entrar-a-mi-empresa" tabindex="-1">Entrar a Mi Empresa <a class="header-anchor" href="#entrar-a-mi-empresa" aria-label="Permalink to &quot;Entrar a Mi Empresa&quot;">​</a></h2><p>En el menú lateral, haz clic en <strong>Mi Empresa</strong>. Verás una pantalla con <strong>pestañas</strong> en la parte superior. Las principales son <strong>Identidad</strong>, <strong>Roles</strong> y <strong>Cargos</strong>.</p><p><img src="'+n+'" alt="Pantalla Mi Empresa con las pestañas Identidad, Roles y Cargos"></p><h2 id="pestana-identidad" tabindex="-1">Pestaña &quot;Identidad&quot; <a class="header-anchor" href="#pestana-identidad" aria-label="Permalink to &quot;Pestaña &quot;Identidad&quot;&quot;">​</a></h2><p>Aquí defines la imagen y los datos básicos de tu empresa:</p><ul><li><strong>Razón social</strong> — el nombre de tu empresa.</li><li><strong>RUT empresa</strong> — se muestra pero <strong>no se puede modificar</strong> (queda fijo desde el registro).</li><li><strong>Color principal</strong> — el color con el que se personaliza la plataforma. Puedes elegir uno de los <strong>colores sugeridos</strong> o abrir el selector de color.</li><li><strong>Logo</strong> — sube el logo de tu empresa (PNG, JPG, SVG o WebP, máximo 2 MB). Si no cargas uno, aparecerá <em>&quot;Sin logo&quot;</em>.</li></ul><p>Cuando termines, haz clic en <strong>Guardar identidad</strong>.</p><blockquote><p>🎨 Personalizar el color y el logo hace que la plataforma se sienta &quot;tuya&quot; y ayuda a que los trabajadores reconozcan que es el sistema oficial de su empresa.</p></blockquote><h2 id="pestana-roles" tabindex="-1">Pestaña &quot;Roles&quot; <a class="header-anchor" href="#pestana-roles" aria-label="Permalink to &quot;Pestaña &quot;Roles&quot;&quot;">​</a></h2><p>Los <strong>roles</strong> definen qué puede hacer cada persona en la plataforma. La empresa viene con roles base, pero desde aquí puedes <strong>crear roles personalizados</strong> y ajustar sus permisos:</p><ul><li><strong>Añadir rol</strong> — crea un nuevo rol con su nombre, descripción y permisos.</li><li><strong>Permisos</strong> — marca qué puede ver y hacer cada rol.</li><li><strong>Eliminar rol</strong> — quita un rol que ya no uses (las personas que lo tenían deberán reasignarse a otro).</li></ul><blockquote><p>🔒 El rol <strong>Administrador</strong> tiene <strong>acceso total</strong> y sus permisos no se pueden editar. Aparece marcado como <em>&quot;Acceso total (no editable)&quot;</em>. Esto evita que alguien se quede sin administrador por error. Revisa <a href="/manual/roles/">Roles de Usuario</a> para entender los roles base.</p></blockquote><p><img src="'+t+'" alt="Pestaña Roles con la lista de roles y sus permisos"></p><h2 id="pestana-cargos" tabindex="-1">Pestaña &quot;Cargos&quot; <a class="header-anchor" href="#pestana-cargos" aria-label="Permalink to &quot;Pestaña &quot;Cargos&quot;&quot;">​</a></h2><p>Los <strong>cargos</strong> son los oficios de obra (carpintero, soldador, jornal, etc.). El catálogo de cargos es importante porque <strong>cada cargo determina qué documentos y capacitaciones de onboarding</strong> necesita un trabajador. Desde aquí mantienes ese catálogo y, en su caso, asocias plantillas de documentos a cada cargo.</p><h2 id="preguntas-frecuentes" tabindex="-1">Preguntas frecuentes <a class="header-anchor" href="#preguntas-frecuentes" aria-label="Permalink to &quot;Preguntas frecuentes&quot;">​</a></h2><p><strong>¿Por qué no puedo cambiar el RUT de la empresa?</strong> El RUT identifica de forma única a tu empresa y queda fijo desde el registro para mantener la integridad de los datos. Si hay un error en el RUT, contacta al soporte.</p><p><strong>Cambié el color y el logo pero no se ven.</strong> Asegúrate de hacer clic en <strong>Guardar identidad</strong>. Luego, si no ves el cambio de inmediato, recarga la página.</p><p><strong>¿Qué diferencia hay entre un rol y un cargo?</strong> El <strong>rol</strong> define los permisos en la plataforma (qué pantallas y acciones puede usar). El <strong>cargo</strong> es el oficio en obra y determina qué documentos de seguridad le corresponden. Consulta el módulo de <a href="/manual/modulos/personas.html">Personas</a>.</p><p><strong>Eliminé un rol que estaba en uso. ¿Qué pasa con esas personas?</strong> Las personas que tenían ese rol deberán reasignarse a otro rol. Por eso conviene revisar quién usa un rol antes de eliminarlo (la lista muestra cuántas personas lo tienen).</p><p><strong>¿Quién puede entrar a Mi Empresa?</strong> Principalmente el <strong>Administrador</strong>. Algunas pestañas pueden estar disponibles para otros roles de gestión según los permisos configurados. Consulta <a href="/manual/roles/">Roles de Usuario</a>.</p>',24)])])}const h=a(l,[["render",i]]);export{q as __pageData,h as default};
